"use strict";
// A crate of settings. Its loader picks its part with a computed require()
// specifier, which scriptc does not compile natively, so the package runs
// in a Node island.
const { createRequire } = require("node:module");
const load = createRequire(__filename);
const [parts] = ["./lib/parts"].map((p) => load(p));

exports.sealed = true;
exports.weight = 12;
exports.label = "apples";
exports.open = parts.open;
Object.defineProperty(exports, "serial", { value: 7, enumerable: false });
exports.unpack = (key) => {
  delete exports[key];
};
